// План specs/admin-access.md, 3.3 (кейс AA-08). Пользователь «בדיקה». Только чтение. @prod-safe
import { test, expect } from '@playwright/test';
import { setLanguage } from '../admin-plans/plans-helpers';
import { DASHBOARD_URL, expectNoAdminPanel, waitForMenu } from './access-helpers';

test.use({ storageState: '../auth/user.json' });

test.describe('Admin Panel — доступ обычного пользователя (#12126fac)', () => {
  test('Browser Back and Forward after the /adminpanel redirect never land on /adminpanel #12126fac @desktop @prod-safe', async ({ page }) => {
    await setLanguage(page, 'en');

    await page.goto('/dashboard');
    await waitForMenu(page);

    await page.goto('/adminpanel');
    await expect(page).toHaveURL(DASHBOARD_URL);

    await page.goBack();
    await expect(page).not.toHaveURL(/\/adminpanel/i);
    await expectNoAdminPanel(page);

    await page.goForward();
    await expect(page).not.toHaveURL(/\/adminpanel/i);
    await expectNoAdminPanel(page);
  });
});
